'use strict';
const HERO='./assets/showroom-banner.webp';
const STORE_KEY='showroom-angela-jaque-v1';
const currencies={ARS:'ARS',BOB:'BOB',USD:'USD'};
const nav=[['inicio','inicio','Inicio'],['inventario','inventario','Prendas'],['caja','caja','Caja'],['ventas','ventas','Ventas'],['gastos','gastos','Gastos'],['reservas','ventas','Reservas'],['looks','ideas','Looks'],['vidriera','vidriera','Vidriera'],['ideas','ideas','Ideas'],['ajustes','ajustes','Ajustes']];
const state={page:'inicio',query:'',filter:'Todas',condition:'Todas',saleQuery:'',cart:[],sort:'recientes',showOnlyAvailable:true,viewSale:null,checkout:{discount:'0',method:'Efectivo',date:nowDate(),note:''}};
let photosReady=false,photoCache={},idb=null,undoFn=null;let db=loadDB(),editingId=null,editImage='',toastTimer=null,imagesDisabled=false;
function blankDB(){return{version:4,createdAt:Date.now(),settings:{store:'Angela y Jaqui',currency:'ARS',dailyGoal:0},products:[],sales:[],expenses:[],reservations:[],looks:[]}}
function loadDB(){try{let d=JSON.parse(localStorage.getItem(STORE_KEY));if(d&&Array.isArray(d.products)&&Array.isArray(d.sales)&&d.settings){d.expenses=Array.isArray(d.expenses)?d.expenses:[];d.reservations=Array.isArray(d.reservations)?d.reservations:[];d.looks=Array.isArray(d.looks)?d.looks:[];if(['Ángela y Jaque','Angela y Jaque'].includes(d.settings.store))d.settings.store='Angela y Jaqui';d.version=4;return d}}catch(e){}return blankDB()}
function save(){try{localStorage.setItem(STORE_KEY,JSON.stringify(db,photosReady?(k,v)=>k==='image'&&typeof v==='string'&&v.startsWith('data:image/')?'':v:null));syncPhotos();document.getElementById('saveStatus').textContent='Guardado en este navegador';return true}catch(e){notify('Sin espacio para guardar. Exportá un respaldo y usá fotos más pequeñas.');return false}}
function h(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function id(){return crypto?.randomUUID?.()||'id'+Date.now().toString(36)+Math.random().toString(36).slice(2,9)}
function money(v){let cur=currencies[db.settings.currency]||'ARS';try{return new Intl.NumberFormat('es-AR',{style:'currency',currency:cur,minimumFractionDigits:0,maximumFractionDigits:2}).format(Number(v)||0)}catch(e){return '$ '+Number(v||0).toLocaleString('es-AR')}}
function nowDate(d=new Date()){let y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`}
function timeLabel(iso){if(!iso)return '';let p=iso.split('-');return p.length===3?`${p[2]}/${p[1]}/${p[0]}`:iso}
function daysSince(timestamp){return Math.floor((Date.now()-Number(timestamp||Date.now()))/86400000)}
function notify(msg,type='success',undo=null){undoFn=undo;
 let el=document.getElementById('toast');
 let warning=/sin |insuficiente|revisá|error|no hay|no quedan|no se pudo|supera|confirmá|vaci/i.test(msg);
 let kind=warning?'warning':type;
 el.className='toast visible '+kind;
 el.innerHTML=`<span class="toast-symbol">${kind==='warning'?'!':symbol('check')}</span><span class="toast-message">${h(msg)}</span>${undo?'<button type="button" class="toast-dismiss" style="width:auto;padding:0 12px;font-weight:700" data-action="undo">Deshacer</button>':''}<button type="button" class="toast-dismiss" aria-label="Cerrar notificación" data-action="dismiss-toast">×</button>`;
 clearTimeout(toastTimer);
 toastTimer=setTimeout(()=>el.classList.remove('visible'),undo?8000:3900);
}
function photo(p){return p&&typeof p.image==='string'&&p.image.startsWith('data:image/')?`<img loading="lazy" alt="${h(p.name)}" src="${p.image}">`:'<span class="empty-photo">👗</span>'}
function miniphoto(p){return `<div class="thumb">${p?photo(p):'<span>👗</span>'}</div>`}
function sold(s){return s&&s.status!=='anulada'}
function saleTotal(s){return Math.max(0,Number(s.subtotal??0)-Number(s.discount??0))}
function saleCost(s){return (s.items||[]).reduce((a,x)=>a+Number(x.cost||0)*Number(x.qty||0),0)}
function summary(){let sales=db.sales.filter(sold),today=nowDate(),todaySales=sales.filter(x=>x.date===today),available=db.products.filter(p=>v4Available(p)>0);let revenue=sales.reduce((a,s)=>a+saleTotal(s),0),cost=sales.reduce((a,s)=>a+saleCost(s),0),expenses=(db.expenses||[]).reduce((a,e)=>a+Number(e.amount||0),0);return{sales,todaySales,revenue,profit:revenue-cost,expenses,operating:revenue-cost-expenses,todayTotal:todaySales.reduce((a,s)=>a+saleTotal(s),0),units:db.products.reduce((a,p)=>a+v4Available(p),0),available:available.length,inventoryCost:db.products.reduce((a,p)=>a+Number(p.cost||0)*Number(p.qty||0),0),inventoryRetail:db.products.reduce((a,p)=>a+Number(p.price||0)*Number(p.qty||0),0)}}
const GLYPHS={
 inicio:'<path d="m3 10 9-7 9 7v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/><path d="M9 21v-8h6v8"/>',
 inventario:'<path d="M6 2h12l2 5-8 5-8-5 2-5Z"/><path d="M12 12v9M3 21h18M4 7l-2 5 10 5 10-5-2-5"/>',
 caja:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 10h18M7 15h4"/>',
 ventas:'<path d="M7 3h10l3 3v15l-3-2-3 2-3-2-3 2-3-2V6z"/><path d="M9 9h6M9 13h7"/>',
 gastos:'<circle cx="12" cy="12" r="9"/><path d="M12 7v10M15 9.5c-.8-.8-5-.9-5 1 0 2 5 1 5 3.5 0 1.7-3.8 2-6 .8"/>',
 vidriera:'<path d="M4 8h16l-1.3 13H5.3L4 8ZM8 9V6a4 4 0 0 1 8 0v3"/>',
 ideas:'<path d="m12 3 1.7 6.3L20 11l-6.3 1.7L12 19l-1.7-6.3L4 11l6.3-1.7L12 3ZM19 19l1 2 1-2 2-1-2-1-1-2-1 2-2 1z"/>',
 ajustes:'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .35 1.87l.07.07-2.83 2.83-.07-.07a1.7 1.7 0 0 0-1.87-.35 1.7 1.7 0 0 0-1.05 1.56V21h-4v-.09a1.7 1.7 0 0 0-1.05-1.56 1.7 1.7 0 0 0-1.87.35l-.07.07-2.83-2.83.07-.07A1.7 1.7 0 0 0 4.6 15a1.7 1.7 0 0 0-1.56-1.05H3v-4h.09A1.7 1.7 0 0 0 4.6 8.95a1.7 1.7 0 0 0-.35-1.87l-.07-.07 2.83-2.83.07.07A1.7 1.7 0 0 0 8.95 4.6 1.7 1.7 0 0 0 10 3.04V3h4v.09a1.7 1.7 0 0 0 1.05 1.56 1.7 1.7 0 0 0 1.87-.35l.07-.07 2.83 2.83-.07.07a1.7 1.7 0 0 0-.35 1.87 1.7 1.7 0 0 0 1.56 1.05H21v4h-.09A1.7 1.7 0 0 0 19.4 15Z"/>',
 mas:'<path d="M5 7h14M5 12h14M5 17h14"/>',
 bag:'<path d="M4 9h16l-1 12H5L4 9zM9 10V7a3 3 0 1 1 6 0v3"/>',
 check:'<path d="m5 12 4 4L19 6"/>'};
function symbol(key){return `<svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${GLYPHS[key]||GLYPHS.ideas}</svg>`}

function renderNav(){
 const desktop=document.getElementById('sideNav'),mobile=document.getElementById('mobileNav');
 desktop.innerHTML=nav.map(([key,ico,label])=>`<button class="navbtn ${state.page===key?'active':''}" data-page="${key}" ${state.page===key?'aria-current="page"':''}><span class="ico">${symbol(ico)}</span><span class="navlabel">${label}</span></button>`).join('');
 const quick=[...nav.filter(x=>['inicio','inventario','caja','ventas'].includes(x[0])),['mas','mas','Más']];
 const count=state.cart.reduce((a,item)=>a+item.qty,0);
 mobile.innerHTML=quick.map(([key,ico,label])=>`<button class="${state.page===key||(key==='mas'&&['gastos','reservas','looks','vidriera','ideas','ajustes'].includes(state.page))?'active':''}" data-page="${key}" aria-label="${label}" ${state.page===key?'aria-current="page"':''}><span class="nav-ico">${symbol(ico)}${key==='caja'&&count?`<i class="nav-count">${count}</i>`:''}</span><span class="nav-text">${label}</span></button>`).join('');
}
function setPage(page){if(page!=='mas'&&!nav.some(x=>x[0]===page))return;state.page=page;state.query='';state.filter='Todas';state.condition='Todas';state.saleQuery='';render();window.scrollTo({top:0,behavior:'instant'})}
function captureCheckout(){
 if(!document.getElementById('saleDate'))return;
 const vals={discount:'discount',method:'method',date:'saleDate',note:'saleNote'};
 for(const [k,id] of Object.entries(vals)){const el=document.getElementById(id);if(el)state.checkout[k]=el.value}
}
function renderCartFloat(){
 const el=document.getElementById('cartFloat'); if(!el)return;
 const count=state.cart.reduce((a,x)=>a+x.qty,0);
 el.hidden=state.page!=='caja'||!count;
 if(!el.hidden){
  document.getElementById('cartFloatCount').textContent=count+' '+(count===1?'prenda':'prendas');
  document.getElementById('cartFloatTotal').textContent=money(state.cart.reduce((sum,item)=>{const p=db.products.find(p=>p.id===item.id);return sum+(p?p.price*item.qty:0)},0));
  requestAnimationFrame(syncFloatingTicketVisibility);
 }
}
function syncFloatingTicketVisibility(){
 const el=document.getElementById('cartFloat');if(!el)return;
 const count=state.cart.reduce((a,x)=>a+x.qty,0);
 const button=document.querySelector('.confirm-sale');
 const r=button?.getBoundingClientRect();
 const alreadyVisible=r&&r.top>=0&&r.bottom<innerHeight-92;
 el.hidden=state.page!=='caja'||count===0||Boolean(alreadyVisible);
}
function renderSaleChoices(){
 let available=db.products.filter(p=>v4Available(p)>0);
 const term=state.saleQuery.toLocaleLowerCase('es-AR').trim();
 const choices=available.filter(p=>[p.name,p.size,p.sku,p.category,p.color].some(x=>String(x||'').toLocaleLowerCase('es-AR').includes(term)));
 return choices.length?choices.map(p=>`<div class="sale-choice">${miniphoto(p)}<div class="sale-choice-detail"><div class="name">${h(p.name)}</div><small>${h(p.size||'Sin talle')} · ${v4Available(p)} disponible${v4Available(p)===1?'':'s'} · <b>${money(p.price)}</b></small></div><button class="btn sm soft sale-add" aria-label="Agregar ${h(p.name)} al ticket" data-action="add-cart" data-id="${h(p.id)}">${symbol('bag')} <span>Agregar</span></button></div>`).join(''):'<div class="empty"><div class="icon">👚</div><h3>Sin coincidencias</h3><p>Probá otra búsqueda o cargá una prenda nueva.</p><button class="btn primary sm" data-action="new">＋ Nueva prenda</button></div>';
}

function render(){captureCheckout();renderNav();let titles={inicio:['Hola Angela y Jaqui','Todo lo que pasa en tu feria, en un solo lugar.'],inventario:['Mi perchero','Fotos, talles y precios bien organizados.'],caja:['Caja rápida ✨','Vendé en pocos toques y actualizá el stock.'],ventas:['Mis ventas','Cada movimiento, con su detalle.'],gastos:['Gastos del showroom','Controlá los gastos de funcionamiento.'],reservas:['Reservas y señas','Apartá prendas y controlá cuándo vence cada reserva.'],looks:['Armá tu look ✨','Combinaciones para enamorar a tus clientas.'],mas:['Más herramientas ✨','Todo lo que necesitás para crecer.'],vidriera:['Vidriera digital','Mostrá lo que tenés y compartilo por WhatsApp.'],ideas:['Ideas para vender','Sugerencias basadas en el inventario real.'],ajustes:['Mi showroom ⚙','Respaldo, moneda y configuración.']};document.getElementById('pageTitle').textContent=titles[state.page][0];document.getElementById('pageSub').textContent=titles[state.page][1];document.getElementById('app').innerHTML=({inicio:home,inventario:inventory,caja:cash,ventas:sales,gastos:expensesPage,reservas:v4ReservationsPage,looks:v4LooksPage,mas:morePage,vidriera:showcase,ideas:ideas,ajustes:settings})[state.page]();renderCartFloat();if(state.page==='caja')updateCheckout();}
function emptyState(title,desc,withDemo=false){return `<div class="empty"><div class="icon">🦋</div><h3>${title}</h3><p>${desc}</p><div class="empty-actions"><button class="btn primary" data-action="new">＋ Cargar primera prenda</button>${withDemo?'<button class="btn" data-action="demo">Ver con prendas de ejemplo</button>':''}</div></div>`}
function home(){let m=summary();let week=Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-6+i);return{date:nowDate(d),label:d.toLocaleDateString('es-AR',{weekday:'short'}).replace('.',''),total:m.sales.filter(s=>s.date===nowDate(d)).reduce((a,s)=>a+saleTotal(s),0)}});let max=Math.max(1,...week.map(x=>x.total));let goal=Math.max(0,Number(db.settings.dailyGoal||0)),goalPct=goal>0?Math.round(m.todayTotal/goal*100):0;let recent=[...m.sales].sort((a,b)=>b.createdAt-a.createdAt).slice(0,5);let low=db.products.filter(p=>v4Available(p)===1).slice(0,5);return backupNotice()+`<section class="hero"><img src="${HERO}" alt="Imagen de marca del Showroom Angela y Jaqui"><div class="hero-info"><span class="eyebrow">TU FERIA • TU ESTILO</span><h2>Tu negocio, organizado con amor.</h2><p>Cada prenda cuenta. Cada venta suma. Acá tenés todo lo que necesitás para crecer.</p><div class="hero-acts"><button class="btn primary" data-action="new">＋ Cargar prenda</button><button class="btn dark" data-page="caja">▣ Cobrar venta</button></div></div></section>
<div class="kpis"><div class="kpi accent"><div class="label">Vendido hoy</div><strong>${money(m.todayTotal)}</strong><span class="meta">${m.todaySales.length} operaciones</span></div><div class="kpi"><div class="label">Prendas disponibles</div><strong>${m.units}</strong><span class="meta">${m.available} modelos con stock</span></div><div class="kpi"><div class="label">Ventas acumuladas</div><strong>${money(m.revenue)}</strong><span class="meta">No incluye anulaciones ni anticipos pendientes</span></div><div class="kpi"><div class="label">Ganancia bruta estimada</div><strong>${money(m.profit)}</strong><span class="meta">Ventas menos costos de prendas</span></div></div>
<section class="panel" style="margin-top:14px"><div class="split"><div><b>🎯 Mi meta de ventas de hoy</b><p class="hint" style="margin:5px 0 0">${goal>0?`${money(m.todayTotal)} de ${money(goal)} · ${goalPct}% alcanzado`:'Elegí una meta diaria en Ajustes para celebrar cada avance.'}</p></div><button class="btn sm" data-page="ajustes">${goal>0?'Cambiar meta':'Definir meta'} →</button></div>${goal>0?`<div class="progress"><div class="progress-fill" style="width:${Math.min(100,goalPct)}%"></div></div><small>${goalPct>=100?'🎉 ¡Meta alcanzada!':`Te faltan ${money(Math.max(0,goal-m.todayTotal))} para alcanzarla.`}</small>`:''}</section>
${db.products.length===0?`<div style="margin-top:17px">${emptyState('¡Tu showroom empieza acá!','Cargá prendas con fotos o probá con ejemplos ficticios para recorrer la aplicación.',true)}</div>`:''}
<div class="heading"><h2>Así venimos esta semana</h2><button class="btn sm" data-page="ventas">Ver movimientos →</button></div><div class="twocol"><section class="panel"><div class="split"><b>Ventas de los últimos 7 días</b><span class="chip pink">${money(week.reduce((a,v)=>a+v.total,0))}</span></div><div class="chart">${week.map(x=>`<div class="barwrap" title="${timeLabel(x.date)} · ${h(money(x.total))}"><div class="bar" style="height:${Math.max(3,x.total/max*130)}px"></div><span>${x.label}</span></div>`).join('')}</div><small>Importes registrados por día de venta.</small></section><section class="panel"><div class="split"><b>Últimas ventas</b><span class="chip">${recent.length}</span></div>${recent.length?recent.map(s=>`<div class="rowitem"><div><b>${timeLabel(s.date)}</b><p>${(s.items||[]).reduce((a,x)=>a+x.qty,0)} prenda(s) · ${h(s.method||'Sin especificar')}</p></div><strong>${money(saleTotal(s))}</strong></div>`).join(''):'<p class="hint">Todavía no registraste ventas. Cuando cobres tu primera prenda, aparecerá acá.</p>'}</section></div>
<section class="panel" style="margin-top:16px"><div class="split" style="flex-wrap:wrap"><div><b>💰 Resultado estimado del negocio</b><p class="hint" style="margin:6px 0 0">Ganancia bruta ${money(m.profit)} − gastos ${money(m.expenses)} = <strong>${money(m.operating)}</strong>. No incluye impuestos ni costos no registrados.</p></div><button class="btn sm soft" data-page="gastos">＋ Anotar gasto</button></div></section>
${v4HomeStrip()}<div class="heading"><h2>Para mirar hoy</h2><button class="btn sm" data-page="ideas">Más ideas ✨</button></div><div class="twocol"><section class="panel"><b>💖 Valor de tu mercadería</b><p style="font-size:25px;font-weight:800;margin:13px 0 5px">${money(m.inventoryRetail)}</p><p class="hint">Valor potencial de venta del stock. Costo de compra del stock físico, incluidas las unidades reservadas: ${money(m.inventoryCost)}.</p></section><section class="panel"><b>👗 Últimas unidades</b>${low.length?low.map(p=>`<div class="rowitem"><div><b>${h(p.name)}</b><p>${h(p.size||'Sin talle')} · ${h(p.condition||'')}</p></div><span class="chip gold">Queda 1</span></div>`).join(''):'<p class="hint">Cuando algún modelo tenga una sola unidad, lo vas a ver acá.</p>'}</section></div>`}
function filteredProducts(){let q=state.query.toLowerCase().trim();let out=db.products.filter(p=>(state.filter==='Todas'||p.category===state.filter)&&(state.condition==='Todas'||p.condition===state.condition)&&(!q||[p.name,p.sku,p.size,p.color,p.category,p.location].some(x=>String(x||'').toLowerCase().includes(q))));return out.sort((a,b)=>state.sort==='precio'?a.price-b.price:state.sort==='mayor'?b.price-a.price:state.sort==='stock'?b.qty-a.qty:b.createdAt-a.createdAt)}
function inventory(){let filtered=filteredProducts();let cats=['Todas','Remeras','Pantalones','Vestidos','Abrigos','Camperas','Polleras','Calzado','Accesorios','Conjuntos','Otros'];return `<div class="toolbar"><input aria-label="Buscar prendas" id="searchInv" class="toolinput search" placeholder="🔎 Buscar prenda, talle, color o código..." value="${h(state.query)}"><select aria-label="Filtrar por categoría" id="filterCategory" class="toolinput">${cats.map(x=>`<option ${state.filter===x?'selected':''}>${x}</option>`).join('')}</select><select id="filterCondition" aria-label="Filtrar por estado" class="toolinput">${['Todas','Nueva','Usada'].map(x=>`<option ${state.condition===x?'selected':''}>${x}</option>`).join('')}</select><select id="filterSort" aria-label="Ordenar prendas" class="toolinput"><option value="recientes" ${state.sort==='recientes'?'selected':''}>Más recientes</option><option value="precio" ${state.sort==='precio'?'selected':''}>Menor precio</option><option value="mayor" ${state.sort==='mayor'?'selected':''}>Mayor precio</option><option value="stock" ${state.sort==='stock'?'selected':''}>Más unidades</option></select></div><div class="split" style="margin-bottom:13px"><span class="muted" style="font-size:12px">${filtered.length} de ${db.products.length} modelos</span><div class="v4-inline-actions"><button class="btn sm" data-action="v4-scan">▦ Escanear QR</button><button class="btn sm" data-action="csv-products">⇩ Exportar CSV</button></div></div>${!db.products.length?emptyState('Perchero listo para llenar','Agregá prendas nuevas o usadas; cada una puede tener su foto, talle, precio, costo y ubicación.',true):!filtered.length?'<div class="empty">No hay prendas con esos filtros. Probá otra búsqueda.</div>':`<div class="product-grid">${filtered.map(cardProduct).join('')}</div>`}`}
function cardProduct(p,showShare=false){let available=v4Available(p),out=available<=0,held=v4Held(p.id);return `<article class="product"><div class="product-photo">${photo(p)}<span class="flag">${out?(held?'Reservada':'Agotada'):h(p.condition||'Prenda')}</span></div><div class="product-info"><span class="chip ${available===1?'gold':available>0?'green':''}">${out?(held?'En reserva':'Sin stock'):available===1?'Última unidad':available+' disponible(s)'}</span><h3 title="${h(p.name)}">${h(p.name)}</h3><div class="details">${h(p.category)} · ${h(p.size||'Sin talle')} ${p.color?'· '+h(p.color):''}</div><div class="product-price"><strong>${money(p.price)}</strong><small>${h(p.sku||'')}</small></div><div class="product-bottom">${showShare?`<button class="btn soft" data-action="share" data-id="${h(p.id)}">↗ Compartir</button>`:`<button class="btn soft" data-action="add-cart" data-id="${h(p.id)}" ${out?'disabled':''}>＋ Vender</button>`}<button class="btn sm v4-reserve-card" data-action="v4-reserve" data-id="${h(p.id)}" ${out?'disabled':''} title="Reservar prenda">♡</button><button class="btn sm" aria-label="Etiqueta de ${h(p.name)}" title="Imprimir etiqueta" data-action="label" data-id="${h(p.id)}">🏷</button><button class="btn edit" aria-label="Editar ${h(p.name)}" title="Editar" data-action="edit" data-id="${h(p.id)}">✎</button></div></div></article>`}
function cartAmount(){let subtotal=state.cart.reduce((a,item)=>{let p=db.products.find(x=>x.id===item.id);return a+(p?p.price*item.qty:0)},0);let discount=Math.max(0,Number(document.getElementById('discount')?.value??state.checkout.discount??0));return{subtotal,discount:Math.min(subtotal,discount),total:Math.max(0,subtotal-discount)}}
function cash(){
 const cartItems=state.cart.filter(item=>db.products.some(p=>p.id===item.id));
 const subtotal=cartItems.reduce((sum,item)=>{const p=db.products.find(p=>p.id===item.id);return sum+(p?p.price*item.qty:0)},0);
 const itemCount=cartItems.reduce((sum,item)=>sum+item.qty,0);
 const c=state.checkout;
 const methods=['Efectivo','Transferencia','Tarjeta','Otro'];
 return `<div class="pos-intro"><span class="eyebrow">VENTAS · FÁCIL Y RÁPIDO</span><p>Elegí las prendas y cobrá en segundos. Cada venta actualiza el inventario.</p></div><div class="posgrid"><section class="panel pos-products"><div class="heading" style="margin-top:0"><div><h2>Elegí las prendas</h2><p>Buscá por nombre, talle o código.</p></div><span class="chip pink">${db.products.filter(p=>v4Available(p)>0).length} modelos</span></div><label class="sr-only" for="saleSearch">Buscar prenda para cobrar</label><div class="search-wrap"><span aria-hidden="true">⌕</span><input id="saleSearch" class="toolinput" placeholder="Buscar para cobrar..." value="${h(state.saleQuery)}" autocomplete="off"></div><button class="btn sm v4-scan-pos" data-action="v4-scan">▦ Escanear etiqueta QR</button><div id="saleChoices" class="sale-select-list" style="margin-top:15px">${renderSaleChoices()}</div></section><section class="panel pos-ticket" id="posTicket"><div class="heading" style="margin-top:0"><div><h2>Tu ticket <span class="ticket-heart">♡</span></h2><p>${itemCount} ${itemCount===1?'prenda seleccionada':'prendas seleccionadas'}</p></div>${itemCount?'<button class="btn sm" data-action="empty-cart">Vaciar</button>':''}</div>${cartItems.length?cartItems.map(item=>{const p=db.products.find(p=>p.id===item.id);return `<div class="cartrow"><div class="cart-product-name"><b>${h(p.name)}</b><small>${money(p.price)} c/u · Talle ${h(p.size||'único')}</small></div><div class="qty"><button aria-label="Quitar una unidad de ${h(p.name)}" data-action="cart-minus" data-id="${h(p.id)}">−</button><b aria-live="polite">${item.qty}</b><button aria-label="Agregar una unidad de ${h(p.name)}" data-action="add-cart" data-id="${h(p.id)}" ${item.qty>=v4Available(p)?'disabled':''}>＋</button></div></div>`}).join(''):'<div class="empty cart-empty"><div class="icon">🛍️</div><h3>Tu ticket está vacío</h3><p>Tocá «Agregar» junto a una prenda y aparecerá acá.</p></div>'}<div class="field checkout-discount"><label for="discount">Descuento ($)</label><input id="discount" type="number" min="0" step="0.01" value="${h(c.discount)}" inputmode="decimal" placeholder="0"></div><div class="formgrid" style="margin-top:13px"><div class="field"><label for="method">Medio de pago</label><select id="method">${methods.map(method=>`<option ${c.method===method?'selected':''}>${method}</option>`).join('')}</select></div><div class="field"><label for="saleDate">Fecha de venta</label><input id="saleDate" type="date" value="${h(c.date||nowDate())}"></div><div class="field span2"><label for="saleNote">Nota / clienta (opcional)</label><input id="saleNote" maxlength="160" value="${h(c.note)}" placeholder="Ej.: María - pago completo"></div></div><div class="totalbox"><div class="sumline"><span>Subtotal</span><b id="checkoutSubtotal">${money(subtotal)}</b></div><div class="sumline"><span>Descuento</span><b id="checkoutDiscount">${money(0)}</b></div><div class="sumline big"><span>Total a cobrar</span><span id="checkoutTotal">${money(subtotal)}</span></div></div><button class="btn primary confirm-sale" ${!itemCount?'disabled':''} data-action="checkout">${symbol('check')} Confirmar venta</button><p class="hint safe-sale">🔒 El stock se descuenta al confirmar.</p></section></div>`;
}
function updateCheckout(){let x=cartAmount();let get=id=>document.getElementById(id);if(get('checkoutTotal')){get('checkoutTotal').textContent=money(x.total);get('checkoutSubtotal').textContent=money(x.subtotal);get('checkoutDiscount').textContent=money(x.discount)}if(get('cartFloatTotal'))get('cartFloatTotal').textContent=money(x.total)}
function sales(){let completed=db.sales.filter(sold).sort((a,b)=>b.createdAt-a.createdAt),voided=db.sales.filter(x=>!sold(x));let total=completed.reduce((a,s)=>a+saleTotal(s),0),profit=completed.reduce((a,s)=>a+saleTotal(s)-saleCost(s),0);return `<div class="kpis" style="margin-top:0;grid-template-columns:repeat(3,minmax(0,1fr))"><div class="kpi accent"><div class="label">Total vendido</div><strong>${money(total)}</strong><div class="meta">Todas las fechas</div></div><div class="kpi"><div class="label">Ganancia bruta estimada</div><strong>${money(profit)}</strong><div class="meta">Sin gastos generales</div></div><div class="kpi"><div class="label">Operaciones</div><strong>${completed.length}</strong><div class="meta">${voided.length} anulada(s)</div></div></div>${salesBreakdown(completed)}<div class="heading"><h2>Historial de caja</h2><div class="chips"><button class="btn sm" data-action="csv-sales">⇩ Exportar CSV</button><button class="btn sm primary" data-page="caja">＋ Cobrar</button></div></div>${!db.sales.length?emptyState('Todavía no hay ventas','Cuando confirmes una venta en Caja, se guardará con fecha, importe, medio de pago y prendas vendidas.'): `<section class="panel table-scroll"><table class="salehistory"><thead><tr><th>Fecha</th><th>Prendas</th><th>Pago</th><th>Total</th><th>Detalle</th></tr></thead><tbody>${[...db.sales].sort((a,b)=>b.createdAt-a.createdAt).map(s=>`<tr><td>${timeLabel(s.date)}${!sold(s)?'<br><span class="chip gold">Anulada</span>':''}</td><td>${(s.items||[]).reduce((a,x)=>a+Number(x.qty||0),0)}</td><td>${h(s.method||'')}</td><td class="money">${money(saleTotal(s))}</td><td><button class="btn sm" data-action="detail-sale" data-id="${h(s.id)}">Ver</button></td></tr>`).join('')}</tbody></table></section>`}`}
function showcase(){let items=db.products.filter(p=>v4Available(p)>0);return `<section class="panel"><div class="split"><div><b>🦋 La vidriera de Angela y Jaqui</b><p class="hint">Elegí una prenda para compartir su descripción y precio por WhatsApp. Las fotos se guardan en tu catálogo local; para enviar la foto, adjuntala en WhatsApp.</p></div><button class="btn primary" data-action="share-all" ${!items.length?'disabled':''}>↗ Compartir lista</button></div></section><div class="heading"><h2>Prendas disponibles</h2><span class="chip pink">${items.length} modelos</span></div>${items.length?`<div class="product-grid">${items.map(p=>cardProduct(p,true)).join('')}</div>`:emptyState('Vidriera vacía','Las prendas con stock van a aparecer acá para que puedas mostrarlas y compartirlas.')}`}
function morePage(){return `<div class="heading" style="margin-top:0"><h2>Herramientas del showroom</h2></div><div class="more-grid"><button class="more-tile" data-page="vidriera"><span>🛍️</span><b>Vidriera</b><small>Compartí productos por WhatsApp</small></button><button class="more-tile" data-page="ideas"><span>✨</span><b>Ideas y promos</b><small>Mensajes listos para vender</small></button><button class="more-tile" data-page="gastos"><span>💸</span><b>Mis gastos</b><small>Sabé cuánto cuesta funcionar</small></button><button class="more-tile" data-page="reservas"><span>🎟️</span><b>Reservas y señas</b><small>Apartá prendas y controlá los vencimientos</small></button><button class="more-tile" data-page="looks"><span>🎀</span><b>Armá tu look</b><small>Creá conjuntos para compartir</small></button><button class="more-tile" data-action="v4-export-catalog"><span>🌐</span><b>Catálogo público</b><small>Exportá la vidriera para GitHub Pages</small></button><button class="more-tile" data-action="v4-copy-catalog-link"><span>🔗</span><b>Enlace a la vidriera</b><small>Copiá el enlace para tus clientas</small></button><button class="more-tile" data-action="v4-scan"><span>▦</span><b>Escanear QR</b><small>Buscá una prenda con la cámara</small></button><button class="more-tile" data-page="ajustes"><span>⚙️</span><b>Ajustes</b><small>Metas, respaldos y exportaciones</small></button></div><div class="notice info">Tu información queda en este navegador. GitHub Pages publica la aplicación, pero no sincroniza inventarios entre teléfonos.</div>`}
function expensesPage(){let list=[...(db.expenses||[])].sort((a,b)=>String(b.date).localeCompare(String(a.date))||Number(b.createdAt)-Number(a.createdAt)),total=list.reduce((a,x)=>a+Number(x.amount||0),0),m=summary();return `<section class="panel"><h2 style="margin:0 0 8px;font:24px Georgia,serif">Registrar un gasto 💸</h2><p class="hint">Anotá los gastos de funcionamiento: alquiler, bolsas, transporte, publicidad, servicios, etc. Los costos de compra de las prendas ya se descuentan en la ganancia bruta de las ventas, así que <b>no los repitas acá</b>.</p><form id="expenseForm" class="formgrid" style="margin-top:18px"><div class="field"><label for="edate">Fecha</label><input id="edate" name="date" type="date" value="${nowDate()}" required></div><div class="field"><label for="ecategory">Tipo de gasto</label><select id="ecategory" name="category"><option>Transporte</option><option>Embalaje / bolsas</option><option>Publicidad</option><option>Alquiler</option><option>Servicios</option><option>Otros</option></select></div><div class="field"><label for="eamount">Importe ($) *</label><input id="eamount" name="amount" type="number" min="0.01" step="0.01" inputmode="decimal" placeholder="Ej.: 2500" required></div><div class="field"><label for="enote">Detalle (opcional)</label><input id="enote" name="note" maxlength="160" placeholder="Ej.: Bolsas para entregar compras"></div><div class="span2"><button class="btn primary" type="submit">＋ Guardar gasto</button></div></form></section><div class="kpis" style="grid-template-columns:repeat(3,minmax(0,1fr))"><div class="kpi"><div class="label">Gastos registrados</div><strong>${money(total)}</strong><div class="meta">${list.length} movimientos</div></div><div class="kpi"><div class="label">Ganancia bruta estimada</div><strong>${money(m.profit)}</strong><div class="meta">Ventas menos costo vendido</div></div><div class="kpi accent"><div class="label">Resultado estimado</div><strong>${money(m.operating)}</strong><div class="meta">Antes de impuestos y otros conceptos</div></div></div><div class="heading"><h2>Historial de gastos</h2><button class="btn sm" data-action="csv-expenses">⇩ Exportar CSV</button></div>${!list.length?'<div class="empty"><div class="icon">🧾</div><h3>Sin gastos todavía</h3><p>Registrá el primer gasto para seguir de cerca el resultado del showroom.</p></div>':`<section class="panel table-scroll"><table class="salehistory"><thead><tr><th>Fecha</th><th>Tipo y detalle</th><th>Importe</th><th></th></tr></thead><tbody>${list.map(e=>`<tr><td>${timeLabel(e.date)}</td><td><b>${h(e.category)}</b><br><small>${h(e.note||'')}</small></td><td class="money">${money(e.amount)}</td><td><button class="btn sm warn" data-action="delete-expense" data-id="${h(e.id)}" aria-label="Eliminar gasto">Eliminar</button></td></tr>`).join('')}</tbody></table></section>`}`}
function saveExpense(form){let data=Object.fromEntries(new FormData(form).entries()),amount=Number(data.amount);if(!Number.isFinite(amount)||amount<=0||amount>1e12||!/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(data.date)||!['Transporte','Embalaje / bolsas','Publicidad','Alquiler','Servicios','Otros'].includes(data.category)){notify('Revisá fecha, categoría e importe.');return}let expense={id:id(),date:data.date,category:data.category,amount,note:String(data.note||'').trim().slice(0,160),createdAt:Date.now()};db.expenses.unshift(expense);if(!save()){db.expenses.shift();return}render();notify('¡Gasto registrado! 💗')}
function deleteExpense(eid){let index=(db.expenses||[]).findIndex(e=>e.id===eid);if(index<0||!confirm('¿Eliminar este gasto del historial?'))return;let expense=db.expenses.splice(index,1)[0];if(!save()){db.expenses.splice(index,0,expense);return}render();notify('Gasto eliminado')}
function csvExpenses(){let rows=[['Fecha','Categoría','Detalle','Importe']];(db.expenses||[]).forEach(e=>rows.push([e.date,e.category,e.note,e.amount]));download(csv(rows),`angela-jaqui-gastos-${nowDate()}.csv`,'text/csv;charset=utf-8')}
function campaignText(type){let active=db.products.filter(p=>Number(p.qty)>0),list=[];let intro='';if(type==='last'){list=active.filter(p=>p.qty===1).slice(0,5);intro='✨ ¡ÚLTIMAS UNIDADES! ✨\nEstas prendas tienen solo una unidad disponible:'}else if(type==='recent'){list=[...active].sort((a,b)=>b.createdAt-a.createdAt).slice(0,5);intro='🦋 Mirá estas prendas de nuestro showroom:'}else if(type==='slow'){list=active.filter(p=>daysSince(p.createdAt)>=30).sort((a,b)=>a.createdAt-b.createdAt).slice(0,5);intro='💖 ¡Volvé a descubrir estas prendas!';}else if(type==='weekend'){list=active.slice(0,5);intro='🎀 ¡Ideas para renovar tu look!';}if(!list.length)return '';return `🦋 *Showroom ${db.settings.store}*\n\n${intro}\n\n${list.map(p=>`• ${p.name}${p.size?' · talle '+p.size:''} — ${money(p.price)}`).join('\n')}\n\n💌 Escribinos para consultar disponibilidad. ¡Te esperamos!`}
async function copyCampaign(type){let message=campaignText(type);if(!message)return notify('Todavía no hay prendas que coincidan con esta idea.');try{await navigator.clipboard.writeText(message);notify('¡Texto copiado! Pegalo en tus estados ♡')}catch(e){prompt('Copiá tu mensaje:',message)}}
function shareCampaign(type){let message=campaignText(type);if(!message)return notify('Todavía no hay prendas que coincidan con esta idea.');openWhatsApp(message)}
function ideas(){let inv=db.products.filter(p=>v4Available(p)>0);let slow=inv.filter(p=>daysSince(p.createdAt)>=30).sort((a,b)=>a.createdAt-b.createdAt);let low=inv.filter(p=>p.qty===1), margins=inv.filter(p=>p.cost>0&&p.price>p.cost).sort((a,b)=>(b.price-b.cost)-(a.price-a.cost));let byCat={};inv.forEach(p=>byCat[p.category]=(byCat[p.category]||0)+p.qty);let cat=Object.entries(byCat).sort((a,b)=>b[1]-a[1])[0];return `<p class="intro">Pequeñas ideas automáticas a partir de los datos que cargues. No son predicciones ni descuentos aplicados: siempre decidís vos qué publicar.</p><div class="check-list"><div class="idea"><h3>⏳ Prendas que esperan una nueva oportunidad</h3><p>${slow.length?`Hay ${slow.length} modelo(s) que llevan 30 días o más cargados y tienen stock. Podrías volver a mostrarlos en estados o armar una promo.`:'Por ahora no aparecen prendas con 30 días o más en inventario.'}</p>${slow.length?`<div class="actionstrip">${slow.slice(0,5).map(p=>`<button class="btn sm soft" data-action="share" data-id="${h(p.id)}">${h(p.name)} (${daysSince(p.createdAt)} días) ↗</button>`).join('')}</div>`:''}</div><div class="idea"><h3>🔥 Última oportunidad</h3><p>${low.length?`Tenés ${low.length} modelo(s) con una sola unidad. Una historia tipo «¡Última unidad!» puede ayudar a comunicar disponibilidad real.`:'Todavía no hay productos con una sola unidad disponible.'}</p>${low.length?`<div class="actionstrip">${low.slice(0,5).map(p=>`<button class="btn sm soft" data-action="share" data-id="${h(p.id)}">${h(p.name)} ↗</button>`).join('')}</div>`:''}</div><div class="idea"><h3>💎 Margen por prenda</h3><p>${margins.length?`La mayor diferencia entre precio y costo cargados está en «${h(margins[0].name)}»: ${money(margins[0].price-margins[0].cost)} por unidad, antes de gastos y descuentos.`:'Cargá precios de costo para conocer qué prendas tienen más margen bruto.'}</p></div><div class="idea"><h3>🎀 Categoría con más unidades</h3><p>${cat?`Actualmente «${h(cat[0])}» concentra ${cat[1]} unidad(es) disponible(s). Podrías organizar un perchero temático o una publicación especial.`:'Cuando cargues stock, vas a ver qué categoría tenés más representada.'}</p></div><div class="idea"><h3>📱 Texto listo para tus estados</h3><p>Armá una lista rápida con las prendas disponibles, para copiarla y difundirla sin volver a escribir todo.</p><div class="actionstrip"><button class="btn sm primary" data-action="share-all">↗ Preparar lista para WhatsApp</button></div><div class="idea" style="background:#fff6fa"><h3>🎬 Creador de historias para vender</h3><p>Generá mensajes con nombres, talles y precios reales. Podés copiar el texto o abrir WhatsApp para enviarlo. Nada se publica sin tu decisión.</p><div class="campaign-grid"><div class="campaign"><b>🔥 Últimas unidades</b><p>Mostrá prendas que tienen una sola unidad.</p><div class="actionstrip"><button class="btn sm soft" data-action="copy-campaign" data-type="last">Copiar</button><button class="btn sm" data-action="share-campaign" data-type="last">WhatsApp ↗</button></div></div><div class="campaign"><b>🦋 Selección reciente</b><p>Destacá las últimas prendas que cargaste.</p><div class="actionstrip"><button class="btn sm soft" data-action="copy-campaign" data-type="recent">Copiar</button><button class="btn sm" data-action="share-campaign" data-type="recent">WhatsApp ↗</button></div></div><div class="campaign"><b>💗 Redescubrir</b><p>Dale visibilidad a prendas cargadas hace 30 días o más.</p><div class="actionstrip"><button class="btn sm soft" data-action="copy-campaign" data-type="slow">Copiar</button><button class="btn sm" data-action="share-campaign" data-type="slow">WhatsApp ↗</button></div></div><div class="campaign"><b>🎀 Inspiración del día</b><p>Compartí una selección de prendas disponibles.</p><div class="actionstrip"><button class="btn sm soft" data-action="copy-campaign" data-type="weekend">Copiar</button><button class="btn sm" data-action="share-campaign" data-type="weekend">WhatsApp ↗</button></div></div></div></div></div>`}
function settings(){return `<div class="twocol"><section class="panel"><h2 style="margin-top:0;font:23px Georgia,serif">Identidad del showroom</h2><form id="settingsForm" class="stack"><div class="field"><label for="storeName">Nombre del negocio</label><input id="storeName" maxlength="60" value="${h(db.settings.store)}"></div><div class="field"><label for="currency">Moneda</label><select id="currency"><option value="ARS" ${db.settings.currency==='ARS'?'selected':''}>Pesos argentinos (ARS)</option><option value="BOB" ${db.settings.currency==='BOB'?'selected':''}>Bolivianos (BOB)</option><option value="USD" ${db.settings.currency==='USD'?'selected':''}>Dólares (USD)</option></select></div><div class="field"><label for="dailyGoal">Meta diaria de ventas (0 para desactivar)</label><input id="dailyGoal" type="number" min="0" step="1" inputmode="numeric" value="${h(db.settings.dailyGoal||0)}"></div><div class="field"><label for="storeWhatsApp">WhatsApp para consultas (con código de país)</label><input id="storeWhatsApp" type="tel" autocomplete="tel" inputmode="tel" maxlength=18 placeholder="Ej.: 5491123456789" value="${h(db.settings.whatsapp||'')}"><small>Se usará en el catálogo público. No lo incluyas si no querés publicarlo.</small></div><p class="hint">Cambiar la moneda solo modifica cómo se muestran los números: no convierte los importes existentes.</p><button class="btn primary" type="submit">Guardar cambios</button></form></section><section class="panel"><h2 style="margin-top:0;font:23px Georgia,serif">Mis respaldos</h2><p class="intro">Esta versión guarda inventario, ventas y gastos en el navegador de este dispositivo. Aunque publiques la app en GitHub Pages, no comparte datos entre celulares ni crea un catálogo público sincronizado.</p>${storageInfo()}<div class="notice">⚠️ Para no perder el trabajo, exportá un respaldo JSON regularmente, especialmente si cambiás de teléfono, cerrás pestañas privadas o borrás datos del navegador.</div><div class="stack"><button class="btn dark" data-action="backup">⇩ Descargar copia completa (.json)</button><button class="btn" data-action="restore">⇧ Restaurar copia (.json)</button><button class="btn" data-action="csv-products">⇩ Inventario en CSV</button><button class="btn" data-action="csv-sales">⇩ Ventas en CSV</button><button class="btn" data-action="csv-expenses">⇩ Gastos en CSV</button></div></section></div><div class="heading"><h2>Herramientas de prueba</h2></div><section class="panel"><div class="split"><div><b>Cargar datos de demostración</b><p class="hint">Agrega prendas ficticias para conocer cómo funciona sin usar mercadería real.</p></div><button class="btn" data-action="demo">＋ Ejemplos</button></div><hr style="border:0;border-top:1px solid var(--line);margin:19px 0"><div class="split"><div><b class="danger-link">Empezar de cero</b><p class="hint">Elimina el inventario y el historial guardados en este navegador.</p></div><button class="btn warn" data-action="clear">Borrar todos los datos</button></div></section><p class="hint" style="margin-top:16px">Versión web premium 4.0 · Funciona en GitHub Pages, sin cuenta ni sincronización en la nube.</p>`}
function openModal(p){editingId=p?.id||null;editImage=p?.image||'';let d=document.getElementById('productDialog'),f=document.getElementById('productForm');f.reset();document.getElementById('modalTitle').textContent=p?'Editar prenda ✎':'Nueva prenda ✨';document.getElementById('deleteProductButton').hidden=!p;document.getElementById('duplicateProductButton').hidden=!p;if(p){for(const key of ['name','category','condition','size','color','cost','price','qty','location','notes']){if(f.elements[key])f.elements[key].value=p[key]??''}}else{f.elements.qty.value=1;f.elements.condition.value='Usada'}updatePreview();d.showModal()}
function updatePreview(){let el=document.getElementById('photoPreview');if(editImage&&editImage.startsWith('data:image/')){el.src=editImage;el.style.opacity='1'}else{el.src='data:image/svg+xml;charset=UTF-8,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="100" height="100"><rect width="100" height="100" fill="#f7e8ee"/><text x="50" y="61" text-anchor="middle" font-size="43">👗</text></svg>');el.style.opacity='.85'}}
async function compressImage(file){if(file.size>15*1024*1024)throw new Error('La foto supera 15 MB. Elegí una más liviana.');let blob=await new Promise((resolve,reject)=>{let img=new Image();let url=URL.createObjectURL(file);img.onload=()=>{try{let scale=Math.min(1,680/Math.max(img.naturalWidth,img.naturalHeight));let c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.naturalWidth*scale));c.height=Math.max(1,Math.round(img.naturalHeight*scale));c.getContext('2d').drawImage(img,0,0,c.width,c.height);c.toBlob(x=>{URL.revokeObjectURL(url);x?resolve(x):reject(new Error('No se pudo procesar la imagen.'))},'image/jpeg',.66)}catch(e){URL.revokeObjectURL(url);reject(e)}};img.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('No se pudo abrir esta imagen.'))};img.src=url});return await new Promise((res,rej)=>{let r=new FileReader();r.onload=()=>res(r.result);r.onerror=()=>rej(new Error('Error leyendo imagen'));r.readAsDataURL(blob)})}
function productSubmit(e){e.preventDefault();let f=e.target,vals=Object.fromEntries(new FormData(f).entries());let price=Number(vals.price),cost=Number(vals.cost||0),qty=Number(vals.qty);if(!vals.name.trim()||!Number.isFinite(price)||price<0||!Number.isFinite(cost)||cost<0||!Number.isSafeInteger(qty)||qty<0){notify('Revisá nombre, cantidades y precios.');return}let existing=db.products.find(p=>p.id===editingId);if(existing&&qty<v4Held(existing.id)){notify('No podés poner menos stock que las unidades con reserva activa.');return}let p={id:existing?.id||id(),sku:existing?.sku||nextSku(),name:vals.name.trim(),category:vals.category,condition:vals.condition,size:vals.size.trim(),color:vals.color.trim(),cost,price,qty,location:vals.location.trim(),notes:vals.notes.trim(),image:editImage,createdAt:existing?.createdAt||Date.now(),updatedAt:Date.now()};let ix=db.products.findIndex(p=>p.id===editingId);if(ix<0)db.products.unshift(p);else db.products[ix]=p;if(!save()){if(ix<0)db.products.shift();else db.products[ix]=existing;return}document.getElementById('productDialog').close();notify(ix>=0?'Prenda actualizada ♡':'¡Nueva prenda en tu showroom! 🦋');render()}
function deleteProduct(){let old=db.products.find(x=>x.id===editingId);if(!old)return;if(v4Held(old.id)>0)return notify('No podés eliminar una prenda con reservas activas. Cancelalas primero.');if(!confirm(`¿Eliminar la prenda «${old.name}» del inventario? Las ventas anteriores permanecerán en el historial.`))return;db.products=db.products.filter(x=>x.id!==editingId);if(!save()){db.products.push(old);return}state.cart=state.cart.filter(x=>x.id!==editingId);closeModal();render();notify('Prenda eliminada del inventario.')}
function printLabel(pid){let p=db.products.find(x=>x.id===pid);if(!p)return;let w=window.open('','_blank','width=450,height=340');if(!w)return notify('Permití ventanas emergentes para imprimir la etiqueta.');w.document.write(`<!DOCTYPE html><html><head><meta charset="utf-8"><title>Etiqueta · ${h(p.name)}</title><style>body{margin:25px;font-family:Arial,sans-serif;color:#172239}.label{width:290px;padding:20px;border:2px solid #172239;text-align:center;border-radius:16px}.store{font-family:Georgia,serif;font-style:italic;font-size:24px;color:#c64b7f}.name{font-size:18px;font-weight:750;margin:18px 0 8px}.price{font-size:38px;font-weight:900;margin:8px}.details{font-size:12px;color:#647086}.sku{font-size:11px;margin-top:10px;letter-spacing:1px}.qr-mark{display:grid;place-items:center;margin-top:7px}.qr-mark svg{width:92px;height:92px}@media print{body{margin:0}.label{border:1px solid #ddd;page-break-inside:avoid}}
.more-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.more-tile{border:1px solid var(--line);background:white;box-shadow:var(--shadow);border-radius:18px;text-align:left;padding:20px;display:flex;flex-direction:column;gap:8px;color:var(--navy)}.more-tile span{font-size:31px}.more-tile b{font-size:16px}.more-tile small{font-size:12px}.more-tile:hover{border-color:#d98ba5}.campaign-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px;margin-top:14px}.campaign{background:#fff;border:1px solid #eedbe5;border-radius:13px;padding:14px}.campaign b{font-size:13px}.campaign p{margin:6px 0 12px;font-size:12px;color:var(--sub);min-height:38px}
@media(max-width:700px){.more-grid{gap:10px}.more-tile{padding:15px}.campaign-grid{grid-template-columns:1fr}.kpis[style*="repeat(3"]{grid-template-columns:1fr!important}.more-tile b{font-size:13px}}
</style></head><body><div class="label"><div class="store">${h(db.settings.store)} 🦋</div><div class="name">${h(p.name)}</div><div class="details">${h(p.condition)} · Talle ${h(p.size||'Consultar')}</div><div class="price">${h(money(p.price))}</div><div class="sku">${h(p.sku)}</div><div class="qr-mark">${window.ShowroomQR?ShowroomQR.svg(p.sku,105):''}</div></div><script>window.onload=()=>window.print();<\/script></body></html>`);w.document.close()}
function addCart(pid){let p=db.products.find(x=>x.id===pid);if(!p||v4Available(p)<=0){notify('Esta prenda no tiene stock.');return}let it=state.cart.find(x=>x.id===pid);if(it&&it.qty>=v4Available(p)){notify('No quedan más unidades de esta prenda.');return}if(it)it.qty++;else state.cart.push({id:pid,qty:1});if(state.page!=='caja')setPage('caja');else render();notify('¡'+p.name+' agregada al ticket!')}
function minusCart(pid){let it=state.cart.find(x=>x.id===pid);if(!it)return;it.qty--;if(it.qty<=0)state.cart=state.cart.filter(x=>x.id!==pid);render()}
function checkout(){let its=state.cart.filter(x=>db.products.some(p=>p.id===x.id));if(!its.length)return notify('Agregá al menos una prenda.');for(let it of its){let p=db.products.find(x=>x.id===it.id);if(v4Available(p)<it.qty)return notify('Stock insuficiente para '+p.name)}let {subtotal,discount,total}=cartAmount(),date=document.getElementById('saleDate').value,method=document.getElementById('method').value,note=document.getElementById('saleNote').value;if(!/^\d{4}-\d{2}-\d{2}$/.test(date))return notify('Elegí una fecha válida.');let sale={id:id(),date,method,note,subtotal,discount,total,createdAt:Date.now(),status:'realizada',items:its.map(x=>{let p=db.products.find(z=>z.id===x.id);return{productId:p.id,name:p.name,qty:x.qty,price:p.price,cost:p.cost,sku:p.sku}})};db.sales.unshift(sale);its.forEach(x=>db.products.find(p=>p.id===x.id).qty-=x.qty);if(!save()){db.sales.shift();its.forEach(x=>db.products.find(p=>p.id===x.id).qty+=x.qty);return}state.cart=[];setPage('ventas');state.checkout={discount:'0',method:'Efectivo',date:nowDate(),note:''};notify(`¡Venta registrada! ${money(total)} 💖`,'success',()=>undoSale(sale.id))}
function showSaleDetail(sid){let s=db.sales.find(x=>x.id===sid);if(!s)return;let el=document.getElementById('productDialog');document.getElementById('modalTitle').textContent='Detalle de venta';let f=document.getElementById('productForm');f.style.display='none';let detail=document.createElement('div');detail.id='saleDetailTemp';detail.className='modal-body';detail.innerHTML=`<p class="hint">${timeLabel(s.date)} · ${h(s.method)} · ${sold(s)?'Realizada':'Anulada'}</p>${s.items.map(x=>`<div class="rowitem"><div><b>${h(x.name)}</b><p>${x.qty} × ${money(x.price)} · ${h(x.sku||'')}</p></div><b>${money(x.qty*x.price)}</b></div>`).join('')}<div class="totalbox"><div class="sumline"><span>Subtotal</span><b>${money(s.subtotal)}</b></div><div class="sumline"><span>Descuento</span><b>${money(s.discount)}</b></div><div class="sumline big"><span>Total</span><span>${money(saleTotal(s))}</span></div>${s.depositApplied?`<div class="sumline"><span>Seña ya recibida</span><b>${money(s.depositApplied)}</b></div><div class="sumline"><span>Saldo cobrado al entregar</span><b>${money(Math.max(0,saleTotal(s)-s.depositApplied))}</b></div>`:''}</div>${s.note?`<p class="hint">Nota: ${h(s.note)}</p>`:''}<div class="dialog-actions"><button class="btn" data-action="receipt" data-id="${h(s.id)}">⧉ Copiar ticket</button>${sold(s)?`<button class="btn warn" data-action="void-sale" data-id="${h(s.id)}">Anular venta</button>`:''}<button class="btn primary" data-action="close-modal">Cerrar</button></div>`;el.appendChild(detail);el.showModal()}
function closeModal(){let d=document.getElementById('productDialog');if(d.open)d.close();let detail=document.getElementById('saleDetailTemp');if(detail)detail.remove();document.getElementById('productForm').style.display='block'}
function voidSale(sid){let s=db.sales.find(x=>x.id===sid);if(!s||!sold(s))return;if(!confirm('¿Anular esta venta y devolver sus unidades al stock? Se conservará en el historial como anulada.'))return;s.status='anulada';if(s.reservationId){let reserved=db.reservations?.find(r=>r.id===s.reservationId);if(reserved)reserved.status='activa'}let restored=[];(s.items||[]).forEach(x=>{let p=db.products.find(p=>p.id===x.productId);if(p){p.qty+=x.qty;restored.push([p,x.qty])}});if(!save()){s.status='realizada';if(s.reservationId){let reserved=db.reservations?.find(r=>r.id===s.reservationId);if(reserved)reserved.status='completada'}restored.forEach(([p,q])=>p.qty-=q);return}closeModal();render();notify('Venta anulada. Se restituyó el stock de los productos existentes.')}
function receipt(s){return `SHOWROOM ${db.settings.store.toUpperCase()}\nVenta: ${timeLabel(s.date)}\n${s.items.map(x=>`${x.qty} x ${x.name} · ${money(x.price*x.qty)}`).join('\n')}\nSubtotal: ${money(s.subtotal)}\nDescuento: ${money(s.discount)}\nTOTAL: ${money(saleTotal(s))}\nPago: ${s.method}${s.depositApplied?'\nSeña previa: '+money(s.depositApplied)+'\nSaldo al entregar: '+money(Math.max(0,saleTotal(s)-s.depositApplied)):''}${s.note?'\nNota: '+s.note:''}\n¡Gracias por tu compra! ♡`}
function shareText(p){return `🦋 *Showroom ${db.settings.store}*\n✨ ${p.name}\n🏷️ Estado: ${p.condition}\n👗 Talle: ${p.size||'Consultar'}${p.color?'\n🎨 Color: '+p.color:''}\n💗 Precio: ${money(p.price)}\n📦 ${v4Available(p)===1?'¡Última unidad!':'Unidades: '+v4Available(p)}\n💬 ¡Consultanos si te gusta!`}
function allText(){return `🦋 *Showroom ${db.settings.store}*\n💗 *Prendas disponibles*\n\n${db.products.filter(p=>p.qty>0).slice(0,70).map(p=>`• ${p.name}${p.size?' (Talle '+p.size+')':''} — ${money(p.price)}${p.qty===1?' ✨ Última unidad':''}`).join('\n')}\n\n💌 ¡Escribinos para consultar!${db.products.filter(p=>p.qty>0).length>70?'\n(Selección de 70 prendas)':''}`}
function openWhatsApp(msg){window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank','noopener,noreferrer')}
function csvCell(x){return '"'+String(x??'').replace(/"/g,'""')+'"'}
function csv(rows){return '\ufeff'+rows.map(x=>x.map(csvCell).join(';')).join('\r\n')}
function download(content,name,type){let blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),8000)}
function backup(){db.settings.lastBackup=Date.now();save();download(JSON.stringify(db,null,2),`angela-jaqui-respaldo-${nowDate()}.json`,'application/json');notify('Copia descargada. Guardala en un lugar seguro.')}
function csvProducts(){let rows=[['Código','Prenda','Categoría','Estado','Talle','Color','Costo','Precio','Cantidad','Ubicación','Notas','Fecha de carga']];db.products.forEach(p=>rows.push([p.sku,p.name,p.category,p.condition,p.size,p.color,p.cost,p.price,p.qty,p.location,p.notes,new Date(p.createdAt).toLocaleDateString('es-AR')]));download(csv(rows),`angela-jaqui-inventario-${nowDate()}.csv`,'text/csv;charset=utf-8')}
function csvSales(){let rows=[['Fecha','Estado','ID venta','Pago','Prenda','Código','Cantidad','Precio unitario','Costo unitario','Subtotal venta','Descuento venta','Total venta','Nota']];db.sales.forEach(s=>(s.items||[]).forEach(x=>rows.push([s.date,s.status,s.id,s.method,x.name,x.sku,x.qty,x.price,x.cost,s.subtotal,s.discount,saleTotal(s),s.note])));download(csv(rows),`angela-jaqui-ventas-${nowDate()}.csv`,'text/csv;charset=utf-8')}
function demo(){if(db.products.length&&!confirm('Se sumarán prendas ficticias a tu inventario actual. ¿Continuar?'))return;let source=[['Campera de jean celeste','Camperas','Usada','M','Celeste',7000,14900,1,40],['Vestido floreado','Vestidos','Usada','S','Rosa',2300,7900,1,21],['Remera básica negra','Remeras','Nueva','M','Negro',4500,9500,4,5],['Jean tiro alto','Pantalones','Usada','40','Azul',4500,12000,1,50],['Sweater tejido beige','Abrigos','Usada','L','Beige',5500,13500,2,10],['Cartera pequeña','Accesorios','Nueva','Único','Lila',4100,10500,3,15]];source.forEach((r,i)=>db.products.push({id:id(),sku:'DEMO-'+(i+1),name:r[0]+' [EJEMPLO]',category:r[1],condition:r[2],size:r[3],color:r[4],cost:r[5],price:r[6],qty:r[7],location:'Perchero de prueba',notes:'Producto ficticio de demostración',image:'',createdAt:Date.now()-r[8]*86400000,updatedAt:Date.now()}));if(!save())return;render();notify('Agregamos 6 prendas ficticias para probar ✨')}
function clearAll(){if(!confirm('ATENCIÓN: Se borrarán todas las prendas y ventas de este navegador. ¿Ya descargaste tu respaldo?'))return;if(!confirm('Última confirmación: esta acción no se puede deshacer sin una copia JSON. ¿Borrar todo?'))return;db=blankDB();state.cart=[];save();setPage('inicio');notify('Datos eliminados de este navegador.')}
async function restore(file){if(!file)return;try{if(file.size>35*1024*1024)throw Error('El archivo es demasiado grande.');let contents=await file.text(),data=JSON.parse(contents);if(!data||!Array.isArray(data.products)||!Array.isArray(data.sales)||!data.settings)throw Error('El archivo no es un respaldo válido.');if(!confirm('Restaurar reemplazará TODAS las prendas y ventas actuales. ¿Continuar?'))return;let prev=db;db={version:4,settings:{store:String(data.settings.store||'Angela y Jaqui').slice(0,60),currency:currencies[data.settings.currency]?data.settings.currency:'ARS',dailyGoal:Math.max(0,Number(data.settings.dailyGoal)||0),skuCounter:Math.max(0,Number(data.settings.skuCounter)||0),lastBackup:Number(data.settings.lastBackup)||0,whatsapp:String(data.settings.whatsapp||'').replace(/\D/g,'').slice(0,15)},createdAt:data.createdAt||Date.now(),products:data.products.map(p=>({...p,id:String(p.id||id()),name:String(p.name||''),sku:String(p.sku||''),qty:Math.max(0,Number(p.qty)||0),price:Math.max(0,Number(p.price)||0),cost:Math.max(0,Number(p.cost)||0),image:typeof p.image==='string'&&p.image.startsWith('data:image/')?p.image:''})),sales:data.sales.filter(s=>s&&typeof s==='object').map(s=>({...s,id:String(s.id||id()),date:/^\d{4}-\d{2}-\d{2}$/.test(s.date)?s.date:nowDate(),method:String(s.method||'Otro').slice(0,40),note:String(s.note||'').slice(0,300),subtotal:Math.max(0,Number(s.subtotal)||0),discount:Math.max(0,Number(s.discount)||0),createdAt:Number(s.createdAt)||Date.now(),status:s.status==='anulada'?'anulada':'realizada',items:(Array.isArray(s.items)?s.items:[]).map(x=>({...x,productId:String(x.productId||''),name:String(x.name||''),qty:Math.max(0,Number(x.qty)||0),price:Math.max(0,Number(x.price)||0),cost:Math.max(0,Number(x.cost)||0),sku:String(x.sku||'')}))})),reservations:Array.isArray(data.reservations)?data.reservations.filter(r=>r&&typeof r==='object').map(v4SanitizeReservation):[],looks:Array.isArray(data.looks)?data.looks.filter(x=>x&&typeof x==='object').map(v4SanitizeLook):[],expenses:Array.isArray(data.expenses)?data.expenses.map(e=>({id:String(e.id||id()),date:String(e.date||nowDate()).slice(0,10),category:String(e.category||'Otros').slice(0,50),amount:Math.max(0,Number(e.amount)||0),note:String(e.note||'').slice(0,160),createdAt:Number(e.createdAt)||Date.now()})):[]};if(!save()){db=prev;return}state.cart=[];setPage('inicio');notify('Copia restaurada correctamente ♡')}catch(e){notify('No se pudo restaurar: '+e.message)}finally{document.getElementById('backupFile').value=''}}
document.addEventListener('click',async e=>{let page=e.target.closest('[data-page]');if(page){setPage(page.dataset.page);return}let btn=e.target.closest('[data-action]');if(!btn)return;let a=btn.dataset.action,pid=btn.dataset.id;if(a==='new')openModal();else if(a==='duplicate-product')duplicateProduct();else if(a==='undo')undoAction();else if(a==='edit'){let p=db.products.find(x=>x.id===pid);if(p)openModal(p)}else if(a==='add-cart')addCart(pid);else if(a==='cart-minus')minusCart(pid);else if(a==='empty-cart'){state.cart=[];render()}else if(a==='checkout')checkout();else if(a==='view-cart'){document.getElementById('posTicket')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})}else if(a==='dismiss-toast'){document.getElementById('toast').classList.remove('visible')}else if(a==='close-modal')closeModal();else if(a==='delete-product')deleteProduct();else if(a==='label')printLabel(pid);else if(a==='remove-photo'){editImage='';document.getElementById('pimage').value='';updatePreview()}else if(a==='backup')backup();else if(a==='restore')document.getElementById('backupFile').click();else if(a==='csv-products')csvProducts();else if(a==='csv-sales')csvSales();else if(a==='csv-expenses')csvExpenses();else if(a==='delete-expense')deleteExpense(pid);else if(a==='copy-campaign')await copyCampaign(btn.dataset.type);else if(a==='share-campaign')shareCampaign(btn.dataset.type);else if(a==='demo')demo();else if(a==='clear')clearAll();else if(a==='detail-sale')showSaleDetail(pid);else if(a==='void-sale')voidSale(pid);else if(a==='receipt'){let s=db.sales.find(x=>x.id===pid);if(s){try{await navigator.clipboard.writeText(receipt(s));notify('Ticket copiado ✓')}catch(e){prompt('Copiá el ticket:',receipt(s))}}}else if(a==='share'){let p=db.products.find(x=>x.id===pid);if(p)await shareProduct(p)}else if(a==='share-all'){let items=db.products.filter(p=>p.qty>0);if(!items.length)return notify('No hay prendas disponibles para compartir.');openWhatsApp(allText())}});
document.addEventListener('input',e=>{if(e.target.id==='searchInv'){let pos=e.target.selectionStart;state.query=e.target.value;let html=filteredProducts().map(cardProduct).join('');let grid=document.querySelector('.product-grid');if(grid){grid.innerHTML=html||'<div class="empty">Sin resultados.</div>'}else{render();let input=document.getElementById('searchInv');if(input){input.focus();input.setSelectionRange(pos,pos)}}let el=document.querySelector('.toolbar+.split .muted');if(el)el.textContent=filteredProducts().length+' de '+db.products.length+' modelos'}else if(e.target.id==='saleSearch'){state.saleQuery=e.target.value;const results=document.getElementById('saleChoices');if(results)results.innerHTML=renderSaleChoices()}else if(e.target.id==='discount'){state.checkout.discount=e.target.value;updateCheckout()}else if(e.target.id==='saleNote'){state.checkout.note=e.target.value}});
document.addEventListener('change',async e=>{let v=e.target.value;if(e.target.id==='filterCategory'){state.filter=v;render()}else if(e.target.id==='filterCondition'){state.condition=v;render()}else if(e.target.id==='filterSort'){state.sort=v;render()}else if(e.target.id==='method'){state.checkout.method=v}else if(e.target.id==='saleDate'){state.checkout.date=v}else if(e.target.id==='pimage'&&e.target.files[0]){try{editImage=await compressImage(e.target.files[0]);updatePreview();notify('Foto lista para guardar 📸')}catch(err){notify(err.message)}}else if(e.target.id==='backupFile'){await restore(e.target.files[0])}});
document.getElementById('productForm').addEventListener('submit',productSubmit);
document.addEventListener('submit',e=>{if(e.target.id==='expenseForm'){e.preventDefault();saveExpense(e.target)}else if(e.target.id==='settingsForm'){e.preventDefault();db.settings.store=document.getElementById('storeName').value.trim()||'Angela y Jaqui';db.settings.currency=document.getElementById('currency').value;db.settings.dailyGoal=Math.max(0,Number(document.getElementById('dailyGoal').value)||0);db.settings.whatsapp=String(document.getElementById('storeWhatsApp').value||'').replace(/\D/g,'').slice(0,15);save();render();notify('Configuración guardada ♡')}});
document.getElementById('productDialog').addEventListener('close',()=>{document.getElementById('saleDetailTemp')?.remove();document.getElementById('productForm').style.display='block'});
render();
window.addEventListener('scroll',syncFloatingTicketVisibility,{passive:true});
window.addEventListener('resize',syncFloatingTicketVisibility,{passive:true});
if('serviceWorker' in navigator && (location.protocol==='https:' || location.hostname==='localhost')){window.addEventListener('load',()=>navigator.serviceWorker.register('./service-worker.js').catch(()=>{}))}

function nextSku(){const n=s=>Number(String(s||'').replace(/^AJ-/,''))||0;let max=Math.max(0,Number(db.settings.skuCounter)||0,...db.products.map(p=>n(p.sku)),...db.sales.flatMap(s=>(s.items||[]).map(x=>n(x.sku))));db.settings.skuCounter=max+1;return 'AJ-'+String(max+1).padStart(4,'0')}
function backupNotice(){if(!db.products.length&&!db.sales.length)return '';let last=Number(db.settings.lastBackup)||0,d=last?Math.floor((Date.now()-last)/86400000):null;if(d!==null&&d<7)return '';return `<div class="notice" style="margin-bottom:14px">⚠️ ${d===null?'Todavía no descargaste ningún respaldo.':'Hace '+d+' días que no descargás un respaldo.'} <button class="btn sm primary" data-action="backup">⇩ Descargar ahora</button></div>`}
function storageInfo(){let n=(localStorage.getItem(STORE_KEY)||'').length,pct=Math.min(100,Math.round(n/5000000*100));return `<p class="hint">Espacio usado en este navegador: <b>${pct}%</b> (aprox.).${pct>=70?' ⚠️ Descargá un respaldo y usá fotos más chicas.':''}</p><div class="progress"><div class="progress-fill" style="width:${pct}%"></div></div>`}
function salesBreakdown(list){if(!list.length)return '';let by={},mon={},ex={},today=nowDate(),tb={};list.forEach(s=>{let t=saleTotal(s),k=s.method||'Otro',m=(s.date||'').slice(0,7)||'s/f';by[k]=(by[k]||0)+t;if(s.date===today)tb[k]=(tb[k]||0)+t;mon[m]=mon[m]||{t:0,p:0,n:0};mon[m].t+=t;mon[m].p+=t-saleCost(s);mon[m].n++});(db.expenses||[]).forEach(e=>{let m=String(e.date||'').slice(0,7);ex[m]=(ex[m]||0)+Number(e.amount||0)});let months=[...new Set([...Object.keys(mon),...Object.keys(ex)])].sort().reverse().slice(0,12);return `<div class="twocol" style="margin-top:14px"><section class="panel"><b>Ventas registradas hoy</b>${Object.keys(tb).length?Object.entries(tb).map(([k,v])=>`<div class="rowitem"><div><b>${h(k)}</b></div><strong>${money(v)}</strong></div>`).join(''):'<p class="hint">Hoy todavía no hay ventas.</p>'}<small>Totales de venta, no movimientos de efectivo: si hubo una seña previa, está incluida en el total de la venta.</small><small>Acumulado: ${Object.entries(by).map(([k,v])=>h(k)+' '+money(v)).join(' · ')}</small></section><section class="panel"><b>Resumen mensual</b>${months.map(m=>{let x=mon[m]||{t:0,p:0,n:0},g=ex[m]||0;return `<div class="rowitem"><div><b>${h(m)}</b><p>${x.n} venta(s) · vendido ${money(x.t)} · gastos ${money(g)}</p></div><strong>${money(x.p-g)}</strong></div>`}).join('')}<small>Resultado = vendido − costo de prendas − gastos.</small></section></div>`}
function duplicateProduct(){let p=db.products.find(x=>x.id===editingId);if(!p)return;let c={...p,name:p.name+' (copia)',id:undefined};closeModal();openModal(c);editingId=null;editImage=p.image||'';updatePreview();document.getElementById('deleteProductButton').hidden=true;document.getElementById('duplicateProductButton').hidden=true;document.getElementById('modalTitle').textContent='Duplicar prenda ✨'}
async function shareProduct(p){try{if(p.image&&navigator.canShare&&navigator.share){let b=await (await fetch(p.image)).blob(),f=new File([b],(p.sku||'prenda')+'.jpg',{type:b.type||'image/jpeg'});if(navigator.canShare({files:[f]})){await navigator.share({files:[f],text:shareText(p)});return}}}catch(e){if(e&&e.name==='AbortError')return}openWhatsApp(shareText(p))}
try{navigator.storage?.persist?.()}catch(e){}
initPhotos();

function undoAction(){let f=undoFn;undoFn=null;document.getElementById('toast').classList.remove('visible');if(f)f()}
function undoSale(sid){let ix=db.sales.findIndex(s=>s.id===sid);if(ix<0)return;let s=db.sales[ix];if(!sold(s))return;let back=[];(s.items||[]).forEach(x=>{let p=db.products.find(p=>p.id===x.productId);if(p){p.qty+=x.qty;back.push([p,x.qty])}});db.sales.splice(ix,1);if(!save()){db.sales.splice(ix,0,s);back.forEach(([p,q])=>p.qty-=q);return}render();notify('Venta deshecha. El stock volvió a su lugar.')}
function idbOpen(){return new Promise((res,rej)=>{let r=indexedDB.open('showroom-photos',1);r.onupgradeneeded=()=>r.result.createObjectStore('photos');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
function idbTx(mode,fn){return new Promise((res,rej)=>{let t=idb.transaction('photos',mode),out=fn(t.objectStore('photos'));t.oncomplete=()=>res(out&&out.result);t.onerror=t.onabort=()=>rej(t.error)})}
async function initPhotos(){try{if(!window.indexedDB)return;idb=await idbOpen();let keys=await idbTx('readonly',s=>s.getAllKeys()),vals=await idbTx('readonly',s=>s.getAll());keys.forEach((k,i)=>photoCache[k]=vals[i]);let put=[];db.products.forEach(p=>{if(!p.image&&photoCache[p.id])p.image=photoCache[p.id];else if(p.image&&photoCache[p.id]!==p.image)put.push(p)});if(put.length){await idbTx('readwrite',s=>{put.forEach(p=>s.put(p.image,p.id))});put.forEach(p=>photoCache[p.id]=p.image)}photosReady=true;save();render()}catch(e){photosReady=false}}
function syncPhotos(){if(!photosReady)return;let ids=new Set(db.products.map(p=>p.id)),put=[],del=[];db.products.forEach(p=>{if(p.image&&photoCache[p.id]!==p.image)put.push(p);else if(!p.image&&photoCache[p.id]!==undefined)del.push(p.id)});Object.keys(photoCache).forEach(k=>{if(!ids.has(k)&&!del.includes(k))del.push(k)});if(!put.length&&!del.length)return;put.forEach(p=>photoCache[p.id]=p.image);del.forEach(k=>delete photoCache[k]);idbTx('readwrite',s=>{put.forEach(p=>s.put(p.image,p.id));del.forEach(k=>s.delete(k))}).catch(()=>{photosReady=false;save();notify('No se pudieron guardar las fotos aparte. Descargá un respaldo.')})}
